CREATE OR REPLACE FUNCTION public.mha_save_company_recipe(p_store_id bigint, p_production_sku_id bigint, p_product_variant_id bigint, p_lines jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_company bigint;v_line jsonb;v_sku bigint;v_qty numeric;\nbegin\n select company_id into v_company from public.mha_current_store_context(p_store_id);\n if not public.mha_has_permission(v_company,'recipe','EDIT') then raise exception 'Recipe edit permission denied' using errcode='42501';end if;\n if not exists(select 1 from public.production_sku where id=p_production_sku_id and company_id=v_company and is_active) then raise exception 'Product not in company';end if;\n if p_product_variant_id is not null and not exists(select 1 from public.product_variant where id=p_product_variant_id and production_sku_id=p_production_sku_id and is_active) then raise exception 'Variant not in product';end if;\n if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)>100 then raise exception 'Invalid recipe lines';end if;\n if p_product_variant_id is null and jsonb_array_length(p_lines)=0 then raise exception 'Base recipe needs ingredients';end if;\n if exists(select 1 from jsonb_array_elements(p_lines) x where jsonb_typeof(x)<>'object' or jsonb_typeof(x->'inventory_sku_id')<>'number' or jsonb_typeof(x->'quantity')<>'number') then raise exception 'Invalid ingredient format';end if;\n if exists(select 1 from (select (x->>'inventory_sku_id')::bigint id,count(*) n from jsonb_array_elements(p_lines) x group by 1 having count(*)>1) duplicates) then raise exception 'Duplicate ingredient';end if;\n for v_line in select value from jsonb_array_elements(p_lines) loop\n  v_sku:=(v_line->>'inventory_sku_id')::bigint;v_qty:=(v_line->>'quantity')::numeric;\n  if v_qty<=0 or v_qty>1000000 or not exists(select 1 from public.inventory_sku where id=v_sku and company_id=v_company and is_active) then raise exception 'Invalid company ingredient or quantity';end if;\n end loop;\n if p_product_variant_id is null then\n  delete from public.product_recipe where production_sku_id=p_production_sku_id;\n  insert into public.product_recipe(production_sku_id,inventory_sku_id,quantity)\n  select p_production_sku_id,(x->>'inventory_sku_id')::bigint,(x->>'quantity')::numeric from jsonb_array_elements(p_lines)x;\n else\n  delete from public.variant_recipe where product_variant_id=p_product_variant_id;\n  insert into public.variant_recipe(product_variant_id,inventory_sku_id,quantity)\n  select p_product_variant_id,(x->>'inventory_sku_id')::bigint,(x->>'quantity')::numeric from jsonb_array_elements(p_lines)x;\n end if;\nend $function$\n

-- Explicit least-privilege grants are required on a fresh migration replay.
REVOKE ALL ON FUNCTION public.mha_save_company_recipe(bigint,bigint,bigint,jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mha_save_company_recipe(bigint,bigint,bigint,jsonb) TO authenticated;
